export function legalMarkup(){
  return "<div class=\"mj-privacy mj-legal\">\n<header class=\"mj-privacy-hero\" aria-labelledby=\"mjLegalTitle\">\n<div class=\"mj-privacy-eyebrow\">AIDE &amp; INFORMATIONS <span aria-hidden=\"true\">✦</span> CADRE DU SITE</div>\n<h1 id=\"mjLegalTitle\">MENTIONS <em>LÉGALES.</em></h1>\n<p>Les informations essentielles concernant l'édition, l'hébergement et l'utilisation de Ma_JesTik, un projet personnel dédié au gaming et à sa communauté.</p>\n<div class=\"mj-privacy-hero-meta\"><span>INFORMATIONS SUR LE SITE</span><span>Mise à jour : <time datetime=\"2026-11-16\">16 novembre 2026</time></span></div>\n</header>\n<div class=\"mj-privacy-intro\" role=\"note\"><span class=\"mj-privacy-intro-symbol\" aria-hidden=\"true\">◈</span><div><strong>Un projet personnel et indépendant</strong>\n<p>Ma_JesTik est un site personnel consacré au gaming et à la communauté. Depuis le 16 novembre 2026, l'hébergement des pages du site est assuré par OVHcloud.</p></div></div>\n<div class=\"mj-privacy-layout\">\n<nav class=\"mj-privacy-nav\" aria-label=\"Sommaire des mentions légales\"><strong>AU SOMMAIRE</strong>\n<button type=\"button\" data-legal-jump=\"presentation\">01 · Présentation</button>\n<button type=\"button\" data-legal-jump=\"edition\">02 · Éditeur &amp; contact</button>\n<button type=\"button\" data-legal-jump=\"hebergement\">03 · Hébergement</button>\n<button type=\"button\" data-legal-jump=\"droits\">04 · Propriété intellectuelle</button>\n<button type=\"button\" data-legal-jump=\"utilisation\">05 · Utilisation du QG</button>\n<button type=\"button\" data-legal-jump=\"donnees\">06 · Données personnelles</button>\n<button type=\"button\" data-legal-jump=\"references\">07 · Références</button>\n</nav>\n<div class=\"mj-privacy-sections\">\n<section class=\"mj-privacy-section\" id=\"mj-legal-presentation\" aria-labelledby=\"mj-legal-presentation-title\">\n<span class=\"mj-privacy-n\">01 / LE PROJET</span><h2 id=\"mj-legal-presentation-title\">PRÉSENTATION DU SITE</h2>\n<p><strong>Nom :</strong> Ma_JesTik — Le QG.</p>\n<p><strong>Adresses :</strong> <a href=\"https://ma-jestik.fr/\">ma-jestik.fr</a> et <a href=\"https://ma-jestik.fr/qg/\">ma-jestik.fr/qg/</a>.</p>\n<p>Ma_JesTik est présenté par son créateur comme un projet personnel non professionnel autour du gaming, du streaming et d'outils communautaires : roue, défis, Killathon, votes, profils et classements.</p>\n<p>Aucune entreprise n'est actuellement déclarée comme éditrice du site. À la date de mise à jour de cette page, le site n'exploite pas de boutique commerciale ni de liens d'affiliation actifs. Une évolution de l'activité pourrait entraîner une révision des présentes mentions.</p>\n</section>\n<section class=\"mj-privacy-section\" id=\"mj-legal-edition\" aria-labelledby=\"mj-legal-edition-title\">\n<span class=\"mj-privacy-n\">02 / QUI PUBLIE ?</span><h2 id=\"mj-legal-edition-title\">ÉDITION &amp; CONTACT</h2>\n<p><strong>Nom d'usage public :</strong> Ma_JesTik (pseudonyme du créateur).</p>\n<p><strong>Contact public :</strong> <a href=\"mailto:contact@ma-jestik.fr\">contact@ma-jestik.fr</a> ou le <a href=\"#/contact\">formulaire Nous contacter</a>.</p>\n<p>L'éditeur a renseigné son identité et ses coordonnées auprès de son hébergeur OVHcloud. Conformément au régime prévu à l'article 1-1, II de la loi pour la confiance dans l'économie numérique (LCEN) pour les éditeurs non professionnels, ses coordonnées personnelles ne sont pas publiées ici.</p>\n<p>Pour l'identification du responsable du traitement des données personnelles, consulte la <a href=\"#/confidentialite\">politique de confidentialité</a>.</p>\n</section>\n<section class=\"mj-privacy-section\" id=\"mj-legal-hebergement\" aria-labelledby=\"mj-legal-hebergement-title\">\n<span class=\"mj-privacy-n\">03 / INFRASTRUCTURE</span><h2 id=\"mj-legal-hebergement-title\">HÉBERGEMENT &amp; SERVICES TECHNIQUES</h2>\n<div class=\"mj-legal-providers\">\n<div><h3>Hébergement du site</h3><p><strong>OVH SAS (OVHcloud)</strong><br>2 rue Kellermann<br>59100 Roubaix — France<br>Téléphone (France) : <a href=\"tel:1007\">1007</a><br><a href=\"https://www.ovhcloud.com/fr/\" target=\"_blank\" rel=\"noopener noreferrer\">OVHcloud</a> · <a href=\"https://www.ovhcloud.com/fr/support/\" target=\"_blank\" rel=\"noopener noreferrer\">Assistance OVHcloud</a></p></div>\n<div><h3>Fonctionnalités et données du QG</h3><p><strong>Cloudflare, Inc.</strong> (Workers et D1)<br>101 Townsend Street<br>San Francisco, CA 94107 — États-Unis<br><a href=\"https://www.cloudflare.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Cloudflare</a></p></div>\n</div>\n<p>OVHcloud assure aussi la gestion du nom de domaine et de la messagerie du site. Les services Cloudflare Workers et D1 assurent les fonctions communautaires et leur stockage. GitHub est utilisé pour la gestion du code source et le déploiement vers OVHcloud ; Resend achemine les messages du formulaire de contact.</p>\n<p class=\"mj-privacy-detail\">Les informations sur les prestataires qui interviennent dans les traitements de données personnelles sont détaillées dans la <a href=\"#/confidentialite\">politique de confidentialité</a>.</p>\n</section>\n<section class=\"mj-privacy-section\" id=\"mj-legal-droits\" aria-labelledby=\"mj-legal-droits-title\">\n<span class=\"mj-privacy-n\">04 / CONTENUS</span><h2 id=\"mj-legal-droits-title\">PROPRIÉTÉ INTELLECTUELLE</h2>\n<p>Les textes, interfaces et éléments originaux du QG sont protégés par les droits de leurs auteurs respectifs. Les marques, noms de jeux, logos, personnages, captures et illustrations de tiers restent la propriété de leurs titulaires et ne deviennent pas la propriété de Ma_JesTik du seul fait de leur présence sur le site.</p>\n<p>Leurs références ne signifient pas que Ma_JesTik est partenaire officiel d'Epic Games, de Twitch, de Discord ou d'un autre éditeur, sauf mention contraire explicite.</p>\n<p>Pour toute question relative à un contenu ou à un droit, écris à <a href=\"mailto:contact@ma-jestik.fr\">contact@ma-jestik.fr</a>.</p>\n</section>\n<section class=\"mj-privacy-section\" id=\"mj-legal-utilisation\" aria-labelledby=\"mj-legal-utilisation-title\">\n<span class=\"mj-privacy-n\">05 / NAVIGATION</span><h2 id=\"mj-legal-utilisation-title\">UTILISATION &amp; LIENS EXTERNES</h2>\n<p>Le QG est proposé comme espace personnel d'information, de divertissement et de participation communautaire. Les modules peuvent évoluer ou être interrompus pour maintenance.</p>\n<p>Certains liens ouvrent des plateformes tierces comme Twitch, Discord et les réseaux sociaux. Leurs propres conditions d'utilisation et politiques de confidentialité s'appliquent lorsque tu quittes Ma_JesTik.</p>\n<p>Les points, classements et récompenses communautaires affichés sur le site ne doivent pas être interprétés comme une monnaie ou comme une promesse de gain financier.</p>\n</section>\n<section class=\"mj-privacy-section\" id=\"mj-legal-donnees\" aria-labelledby=\"mj-legal-donnees-title\">\n<span class=\"mj-privacy-n\">06 / RESPECT DES VISITEURS</span><h2 id=\"mj-legal-donnees-title\">DONNÉES PERSONNELLES</h2>\n<p>Pour connaître les données utilisées lors de la connexion Twitch, de la participation au QG ou d'une prise de contact, consulte la <a href=\"#/confidentialite\">politique de confidentialité</a>.</p>\n<p>Tu peux poser une question, signaler un contenu ou demander l'exercice de tes droits via <a href=\"mailto:contact@ma-jestik.fr\">contact@ma-jestik.fr</a> ou la <a href=\"#/contact\">page de contact</a>.</p>\n<p>La politique de confidentialité identifie le responsable du traitement, décrit les finalités, les prestataires, les durées de conservation et les moyens d'exercer tes droits.</p>\n</section>\n<section class=\"mj-privacy-section\" id=\"mj-legal-references\" aria-labelledby=\"mj-legal-references-title\">\n<span class=\"mj-privacy-n\">07 / TEXTES DE RÉFÉRENCE</span><h2 id=\"mj-legal-references-title\">RÉFÉRENCES &amp; MISES À JOUR</h2>\n<p>Les présentes informations peuvent évoluer si les conditions d'hébergement, les fonctionnalités ou le statut de l'activité changent.</p>\n<ul class=\"mj-legal-sources\"><li><a href=\"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000049568614/\" target=\"_blank\" rel=\"noopener noreferrer\">Loi n° 2004-575 — article 1-1 (LCEN)</a></li>\n<li><a href=\"https://www.ovhcloud.com/fr/terms-and-conditions/\" target=\"_blank\" rel=\"noopener noreferrer\">OVHcloud — mentions légales officielles</a></li>\n<li><a href=\"https://www.cloudflare.com/privacypolicy/\" target=\"_blank\" rel=\"noopener noreferrer\">Cloudflare — coordonnées officielles</a></li>\n</ul>\n</section>\n</div></div><div class=\"mj-privacy-bottom\"><span aria-hidden=\"true\">✦</span> MA_JESTIK · DES INFORMATIONS ACCESSIBLES, UN QG INDÉPENDANT.</div></div>";
}

export function mountLegal(){
  const root=document.querySelector('.mj-legal');
  if(!root)return;
  root.addEventListener('click', event=>{
    const button=event.target.closest('[data-legal-jump]');
    if(!button||!root.contains(button))return;
    const target=root.querySelector('#mj-legal-'+button.dataset.legalJump);
    if(!target)return;
    target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
    const heading=target.querySelector('h2');
    heading?.setAttribute('tabindex','-1');
    heading?.focus({preventScroll:true});
  });
}
